<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import AdminShell from '@/layouts/AdminShell.vue'
import http, { getErrorMessage } from '@/api/http'

type Option = { id: string; name: string }
type Settlement = { name: string; postal_code: string }
type PostalLookup = { postal_code: string; state: string; municipality: string; neighborhoods: string[] }

const form = ref({ name: '', rfc: '', contact_email: '', street_address: '', neighborhood: '', postal_code: '', state: '', municipality: '' })
const states = ref<Option[]>([]); const municipalities = ref<Option[]>([]); const settlements = ref<Settlement[]>([])
const selectedState = ref(''); const selectedMunicipality = ref(''); const selectedSettlement = ref(''); const neighborhoodQuery = ref('')
const photo = ref<File | null>(null); const previewUrl = ref(''); const loadingLocation = ref(false); const saving = ref(false); const submitted = ref(false)
const error = ref(''); const success = ref('')
const rfcValid = computed(() => /^(?:[A-ZÑ&]{3}|[A-ZÑ&]{4})\d{2}(0[1-9]|1[0-2])(0[1-9]|[12]\d|3[01])[A-Z0-9]{3}$/.test(form.value.rfc.trim().toUpperCase()))
const formValid = computed(() => Boolean(form.value.name.trim() && rfcValid.value && /^\S+@\S+\.\S+$/.test(form.value.contact_email) && form.value.street_address.trim() && form.value.neighborhood && /^\d{5}$/.test(form.value.postal_code) && form.value.state && form.value.municipality && photo.value))

function clearMessages() { error.value = ''; success.value = '' }
function handlePhoto(event: Event) { const file = (event.target as HTMLInputElement).files?.[0] ?? null; photo.value = file; if (previewUrl.value) URL.revokeObjectURL(previewUrl.value); previewUrl.value = file ? URL.createObjectURL(file) : '' }
function stateName() { return states.value.find(option => option.id === selectedState.value)?.name ?? '' }
function municipalityName() { return municipalities.value.find(option => option.id === selectedMunicipality.value)?.name ?? '' }

async function loadStates() { loadingLocation.value = true; try { states.value = (await http.get<Option[]>('/workshops/location/states')).data } catch (exception) { error.value = getErrorMessage(exception) } finally { loadingLocation.value = false } }
async function loadMunicipalities() { clearMessages(); municipalities.value = []; settlements.value = []; selectedMunicipality.value = ''; selectedSettlement.value = ''; form.value.state = stateName(); form.value.municipality = ''; form.value.neighborhood = ''; if (!selectedState.value) return; loadingLocation.value = true; try { municipalities.value = (await http.get<Option[]>(`/workshops/location/states/${selectedState.value}/municipalities`)).data } catch (exception) { error.value = getErrorMessage(exception) } finally { loadingLocation.value = false } }
function selectMunicipality() { settlements.value = []; selectedSettlement.value = ''; form.value.municipality = municipalityName(); form.value.neighborhood = ''; clearMessages() }
async function lookupPostalCode() { if (!/^\d{5}$/.test(form.value.postal_code)) return; clearMessages(); loadingLocation.value = true; try { const { data } = await http.get<PostalLookup>(`/workshops/location/postal-codes/${form.value.postal_code}`); form.value.state = data.state; form.value.municipality = data.municipality; settlements.value = data.neighborhoods.map(name => ({ name, postal_code: data.postal_code })); form.value.neighborhood = settlements.value.length === 1 ? settlements.value[0].name : ''; selectedSettlement.value = settlements.value.length === 1 ? `${settlements.value[0].postal_code}::${settlements.value[0].name}` : ''; selectedState.value = states.value.find(option => option.name === data.state)?.id ?? ''; if (selectedState.value) { municipalities.value = (await http.get<Option[]>(`/workshops/location/states/${selectedState.value}/municipalities`)).data; selectedMunicipality.value = municipalities.value.find(option => option.name === data.municipality)?.id ?? '' } } catch (exception) { error.value = getErrorMessage(exception); settlements.value = [] } finally { loadingLocation.value = false } }
async function searchNeighborhood() { if (!form.value.state || !form.value.municipality || neighborhoodQuery.value.trim().length < 3) { error.value = 'Selecciona estado y municipio, y escribe al menos 3 caracteres de la colonia.'; return } clearMessages(); loadingLocation.value = true; try { settlements.value = (await http.get<Settlement[]>('/workshops/location/settlements', { params: { state: form.value.state, municipality: form.value.municipality, query: neighborhoodQuery.value } })).data; if (!settlements.value.length) error.value = 'No se encontraron colonias para esa ubicación.' } catch (exception) { error.value = getErrorMessage(exception) } finally { loadingLocation.value = false } }
function chooseSettlement(settlement: Settlement) { form.value.neighborhood = settlement.name; form.value.postal_code = settlement.postal_code; clearMessages() }
function chooseSelectedNeighborhood() { const settlement = settlements.value.find(item => `${item.postal_code}::${item.name}` === selectedSettlement.value); if (settlement) chooseSettlement(settlement) }

async function submit() { submitted.value = true; clearMessages(); if (!formValid.value) { error.value = 'Completa todos los campos y selecciona una fotografía válida.'; return } saving.value = true; try { const data = new FormData(); Object.entries(form.value).forEach(([key, value]) => data.append(key, key === 'rfc' ? value.toUpperCase().trim() : value)); data.append('photo', photo.value as File); const response = await http.post<{ name: string }>('/workshops', data, { headers: { 'Content-Type': 'multipart/form-data' } }); success.value = `El taller “${response.data.name}” fue registrado correctamente.`; form.value = { name: '', rfc: '', contact_email: '', street_address: '', neighborhood: '', postal_code: '', state: '', municipality: '' }; selectedState.value = ''; selectedMunicipality.value = ''; selectedSettlement.value = ''; settlements.value = []; neighborhoodQuery.value = ''; photo.value = null; previewUrl.value = ''; submitted.value = false } catch (exception) { error.value = getErrorMessage(exception) } finally { saving.value = false } }
onMounted(loadStates)
</script>

<template><AdminShell><section class="workshop-heading"><div><p class="eyebrow">Registro de establecimiento</p><h1>Alta del taller mecánico</h1><p>Captura la información fiscal, ubicación y una fotografía del establecimiento.</p></div></section><p v-if="error" class="notice error" role="alert">{{ error }}</p><p v-if="success" class="notice success" role="status">{{ success }}</p><form class="workshop-form" novalidate @submit.prevent="submit"><section class="workshop-card"><h2>Información general y fiscal</h2><div class="workshop-fields"><label>Nombre del taller mecánico<input v-model.trim="form.name" maxlength="120" autocomplete="organization" placeholder="Ej. Taller Los Pinos" /><span v-if="submitted && !form.name.trim()">El nombre es obligatorio.</span></label><label>RFC<input v-model="form.rfc" maxlength="13" placeholder="XAXX010101000" @input="form.rfc = form.rfc.toUpperCase()" /><span v-if="submitted && !rfcValid">Ingresa un RFC mexicano válido de 12 o 13 caracteres.</span></label><label class="full">Email de contacto<input v-model.trim="form.contact_email" type="email" autocomplete="email" placeholder="contacto@taller.com" /><span v-if="submitted && !/^\S+@\S+\.\S+$/.test(form.contact_email)">Ingresa un correo electrónico válido.</span></label></div></section><section class="workshop-card"><div class="section-title"><div><h2>Ubicación</h2><p>Busca por código postal o selecciona estado, municipio y colonia.</p></div><span v-if="loadingLocation" class="loading">Consultando ubicación…</span></div><div class="workshop-fields"><label>Código postal<input v-model="form.postal_code" inputmode="numeric" maxlength="5" placeholder="06600" @blur="lookupPostalCode" /><small>Al ingresar 5 dígitos se completan estado, municipio y colonias.</small><span v-if="submitted && !/^\d{5}$/.test(form.postal_code)">Debe contener 5 dígitos.</span></label><label>Estado<select v-model="selectedState" :disabled="loadingLocation" @change="loadMunicipalities"><option value="">Selecciona un estado</option><option v-for="option in states" :key="option.id" :value="option.id">{{ option.name }}</option></select></label><label>Municipio o alcaldía<select v-model="selectedMunicipality" :disabled="!selectedState || loadingLocation" @change="selectMunicipality"><option value="">Selecciona un municipio</option><option v-for="option in municipalities" :key="option.id" :value="option.id">{{ option.name }}</option></select></label><label>Buscar colonia<div class="inline-search"><input v-model.trim="neighborhoodQuery" placeholder="Escribe al menos 3 caracteres" /><button type="button" class="secondary-button" :disabled="loadingLocation" @click="searchNeighborhood">Buscar</button></div><small>Selecciona antes el estado y municipio para consultar la API.</small></label><label>Colonia<select v-model="selectedSettlement" :disabled="!settlements.length" @change="chooseSelectedNeighborhood"><option value="">Selecciona una colonia</option><option v-for="option in settlements" :key="`${option.name}-${option.postal_code}`" :value="`${option.postal_code}::${option.name}`">{{ option.name }} · CP {{ option.postal_code }}</option></select><span v-if="submitted && !form.neighborhood">Selecciona una colonia.</span></label><label class="full">Calle y número<input v-model.trim="form.street_address" maxlength="180" autocomplete="street-address" placeholder="Av. Principal 123" /><span v-if="submitted && !form.street_address.trim()">La calle y número son obligatorios.</span></label></div></section><section class="workshop-card photo-card"><div><h2>Fotografía del taller</h2><p>Selecciona una sola imagen JPG, PNG o WEBP de hasta 5 MB.</p></div><label class="photo-drop"><input type="file" accept="image/jpeg,image/png,image/webp" @change="handlePhoto" /><span>{{ photo ? photo.name : 'Seleccionar fotografía' }}</span></label><img v-if="previewUrl" class="photo-preview" :src="previewUrl" alt="Vista previa de la fotografía del taller" /><span v-if="submitted && !photo" class="field-error">La fotografía es obligatoria.</span></section><button class="primary-button submit-workshop" type="submit" :disabled="saving">{{ saving ? 'Registrando…' : 'Registrar taller mecánico' }}</button></form></AdminShell></template>
